import { randomBytes } from 'node:crypto'

/**
 * Donation references are generated by the server only (never accepted from a browser) and are unguessable: 128 random
 * bits. Paystack allows only `-`, `.`, `=` and alphanumerics in a reference, so the format is `CTG-` + 32 lowercase hex.
 * Anything that is not exactly this shape is rejected before it reaches the database or a provider URL.
 */

export const REFERENCE_RE = /^CTG-[0-9a-f]{32}$/

export const generateDonationReference = (): string => `CTG-${randomBytes(16).toString('hex')}`

export const isDonationReference = (value: unknown): value is string =>
  typeof value === 'string' && REFERENCE_RE.test(value)
